        int ch = bb.get(i) & 0xff;
        if ((ch & 0xC0) == 0xC0) { // High surrogate
            int lowCh = bb.get(++i) & 0xff;
            if ((lowCh & 0xFC) == 0xFC) { // Legal Supplementary Characters
                sb.append((char) (((ch & 0x03FF) << 10) | (lowCh & 0x03FF)));
                i++;
            } else { // Malformed Supplementary Characters
