public List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }

    long duration = end - start;
    if (duration >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Time interval must be less than FETCH_DATA_DURATION milliseconds");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    Date tempDate = new Date(start);
    for (int i = 0; i < 1000 * FETCH_DATA_DURATION; i++) { 
        // Calculate the start and end times for the current iteration
        long newStart = tempDate.getTime();
        long newEnd = newStart + FETCH_DATA_DURATION;

        // Check if the new end time exceeds the boundary
        if (newEnd > end) {
            newEnd = end;
        }

        // Create a new TimeRange and add it to the list
        timeRanges.add(new TimeRange(newStart, newEnd));
        tempDate.setTime(newEnd);
    }

    return timeRanges;
}

