public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int charValue = (str.charAt(i) & 0xff);
        if (charValue >= 0 && charValue <= 127) {
            size++;
        } else if (charValue >= 128 && charValue <= 191) {
            size += 2;
        } else if (charValue >= 192 && charValue <= 223) {
            size += 3;
        } else if (charValue >= 224 && charValue <= 239) {
            size += 4;
        } else if (charValue >= 240 && charValue <= 243) {
            size += 5;
        } else if (charValue >= 244 && charValue <= 246) {
            size += 6;
        } else if (charValue >= 247 && charValue <= 251) {
            size += 7;
        }
    }
    return size;
}

