public String format(final LoggingEvent event) {
    StringBuilder formattedEvent = new StringBuilder();

    // Format event timestamp
    formattedEvent.append("[").append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(event.getTimeStamp())).append("] ");

    // Format logging level
    formattedEvent.append(event.getLevel().toString()).append(" ");

    // Format thread name
    formattedEvent.append("* ").append(Thread.currentThread().getName()).append(" * ");

    // Format caller class name (optional)
    try {
        StackTraceElement[] stackTrace = new java.util.Arrays.asList(Thread.currentThread().getStackTrace()).toArray(new StackTraceElement[0]);
        StackTraceElement caller = null;
        for (int i = stackTrace.length - 1; i >= 0; i--) {
            if (!callers[i].getClassName().equals(Math.class.getName())) {
                caller = callers[i];
                break;
            }
        }
        if (caller != null) {
            formattedEvent.append(caller.getClassName()).append("; ").append(caller.getMethodName()).append("; Line: ");
            formattedEvent.append(caller.getLineNumber()).append(" ");
        }
    } catch (Exception e) {
        e.printStackTrace();
        formattedEvent.append("Unknown Caller");
    }

    // Format message
    formattedEvent.append(event.getMessage());

    // Append thread name and stack trace to the formatted event
    formattedEvent.append("* ").append(Thread.currentThread().getName()).append(" * ");
    StackTraceElement[] stackTrace = new java.util.Arrays.asList(Thread.currentThread().getStackTrace()).toArray(new StackTraceElement[0]);
    for (int i = stackTrace.length - 1; i >= 0; i--) {
        formattedEvent.append(caller.getClassName()).append("; ").append(caller.getMethodName()).append("; Line: ");
        formattedEvent.append(caller.getLineNumber()).append(" ");
    }

    return formattedEvent.toString();
}

