public String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int length = str.length();
    boolean escaped = false;

    for (int i = 0; i < length; i++) {
        if (escaped) {
            switch (str.charAt(i)) {
                case 'b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case '"':
                    result.append("\"");
                    break;
                case '\\':
                    result.append("\\");
                    break;
            }
            escaped = false;
        } else {
            if (str.charAt(i) == '\\') {
                escaped = true;
            } else {
                result.append(str.charAt(i));
            }
        }
    }

    return result.toString();
}

