    // Iterate through each set in the bucketsByLabel list
    for (Set<Integer> bucket : bucketsByLabel) {
        // If the bucket label matches minLabel, move all its entries to bucket 0
        if (bucket.contains(minLabel)) {
            // Remove minLabel from the current bucket
            bucket.remove(minLabel);
            // Add minLabel to bucket 0
            bucket.add(0, minLabel);
            // Update the label of bucket 0 if it has entries
            if (bucket.isEmpty()) {
                // If bucket 0 becomes empty, remove it from the bucketsByLabel list
                bucketsByLabel.remove(bucket);
            } else {
                // Update labels of vertices in bucket 0
                for (int vertex : bucket) {
                    labels.set(vertex, 0);
                }
            }
        }
    }
}

