public void abbreviate(final int nameStart,final StringBuffer buf) {
    if (buffer == null || nameStart < 0 || nameStart >= buffer.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    String name = buffer.substring(nameStart);
    int abbreviationStart = 0;
    int abbreviationLength = 1;

    while (abbreviationLength < name.length() && Character.isUpperCase(name.charAt(abbreviationStart))) {
        ++abbreviationLength;
    }

    abbreviationStart -= 2; // avoid backtracking past first character

    if (abbreviationLength > 1) {
        buf.append(name, abbreviationStart, abbreviationStart + abbreviationLength);
    } else { // if abbreviation is one character, add a dot after it
        buf.append(name.charAt(abbreviationStart));
        buf.append('.');
    }
}

