private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    Set<V> inducedVertices = new HashSet<>(graph.vertexSet());
    inducedVertices.retainAll(vertices);
    if(inducedVertices.size() < 2) return true;

    int degree = inducedVertices.size();

    for(V vertex : inducedVertices){
        Set<E> edges = graph.edgesOf(vertex);
        if(edges.size() < degree || edges.size() > degree){
            return false;
        }
    }

    return true;
}

