Edge edgeToNext() {
    if (this._nodes == null || this._edges == null || this._nodes.isEmpty() || this._edges.isEmpty()) {
        throw new IllegalArgumentException("Graph is empty");
    }

    Node currentNode = this._nodes.iterator().next();
    List<Edge> sortedEdges = new ArrayList<>(this._edges);

    Collections.sort(sortedEdges, new Comparator<Edge>() {
        @Override
        public int compare(Edge e1, Edge e2) {
            Node from1 = e1.getFrom();
            Node to1 = e1.getTo();
            Node from2 = e2.getFrom();
            Node to2 = e2.getTo();

            return Integer.compare(from1.getId() != from2.getId() ? from1.getId() : to1.getId(),
                    Integer.compare(to1.getId() != to2.getId() ? to1.getId() : to2.getId()));
        }
    });

    Edge currentEdge = sortedEdges.stream().findFirst().orElse(null);
    if (currentEdge == null) {
        throw new NoSuchElementException("No edge found beyond the current node");
    }
    this._nodes.remove(currentNode);
    this._edges.remove(currentEdge);
    this._nodes.add(currentEdge.getTo());

    return currentEdge;
}

